        private static P3CpuSnap P3CpuRead()
        {
            long created,exited; var s = new P3CpuSnap(); var thread = GetCurrentThread();
            if (!QueryPerformanceCounter(out s.begin) || !GetThreadTimes(thread,out created,out exited,out s.kernel,out s.user) || !QueryThreadCycleTime(thread,out s.cycles) || !QueryPerformanceCounter(out s.end))
                throw new InvalidOperationException("Thread CPU diagnostic API unavailable");
            s.gc=GC.CollectionCount(0); return s;
        }
        private static P3CpuSnap P3CpuStart()
        {
            if (p3CpuFrequency == 0)
            {
                if (!QueryPerformanceFrequency(out p3CpuFrequency)) throw new InvalidOperationException("QPC frequency unavailable");
                p3CpuThread=GetCurrentThreadId();
                P3CpuRead(); // Warm native entry points before measuring empty reads.
                for(int i=0;i<257;i++)p3CpuEmpty.Add(P3CpuRead());
            }
            if (GetCurrentThreadId()!=p3CpuThread) throw new InvalidOperationException("Navigation moved threads during diagnostic");
            return P3CpuRead();
        }
